/**
 * Crear una tarjeta(card) de etapa.
 *
 * @param {Object} etapa Datos de la etapa.
 * @param {Object} etapa_anterior_orden_8 Etapa con el orden inmediatamente anterior al orden 8.
 * @returns {string} HTML de la card.
 * @author Andres Morales
 * @author Andres Gonzalez
 * @author Jair Carvajal
 */
function crearTarjetaEtapa(etapa, etapa_anterior_orden_8) {
    let etapa_anterior_contracion = false;

    if (etapa_anterior_orden_8 && etapa.orden === etapa_anterior_orden_8.orden && etapa.activa == 1) {
        etapa_anterior_contracion = true;
    }

    // Detectar si es etapa de prueba técnica sin archivos
    let es_prueba_tecnica = etapa.nombre === 'Prueba técnica';
    let tiene_prueba_tecnica_cargada = etapa?.prueba_cargada ?? true;

    let candidatos_html = '';
    let candidatos_totales = 0;
    let candidatos_completaron = 0;

    // Mostrar mensaje si es prueba técnica sin archivos
    if (es_prueba_tecnica && !tiene_prueba_tecnica_cargada) {
        let html = crearMensajeSinArchivosInstrucciones(etapa.id);

        // Si hay candidatos, agregarlos después del mensaje
        if (etapa?.usuarios_vacantes?.length > 0) {
            etapa.usuarios_vacantes.forEach((usuario_vacante) => {
                html += crearCardCandidato(usuario_vacante, 'listado', etapa.nombre, etapa_anterior_contracion);
            });
            candidatos_totales = etapa.usuarios_vacantes.length;
            candidatos_completaron = etapa.usuarios_vacantes.filter((usuario_vacante) => usuario_vacante.puntaje !== null || usuario_vacante.puntaje_ia !== null).length;
        }

        candidatos_html = `<div class="candidatos-container">${html}</div>`;
    } else if (etapa?.usuarios_vacantes?.length > 0) {
        let html = '';

        etapa.usuarios_vacantes.forEach((usuario_vacante) => {
            html += crearCardCandidato(usuario_vacante, 'listado', etapa.nombre, etapa_anterior_contracion);
        });

        candidatos_html = `<div class="candidatos-container">${html}</div>`;
        candidatos_totales = etapa.usuarios_vacantes.length;
        candidatos_completaron = etapa.nombre === 'Documentos para contratación'
            ? etapa.usuarios_vacantes.filter((usuario_vacante) => usuario_vacante.etapa_completada === true).length
            : etapa.usuarios_vacantes.filter((usuario_vacante) => usuario_vacante.puntaje !== null || usuario_vacante.puntaje_ia !== null).length;
    } else {
        candidatos_html = `
            <div class="d-flex justify-content-center align-items-center my-5"><div class="etapa-icono-circulo"><i class="bi bi-arrow-90deg-right"></i></div></div>
            <div class="mt-auto pb-10 px-5"><p class="text-headline-5 text-gray-40 text-center mb-5 pb-10 px-6">Mueve candidatos con el botón o arrástralos desde la etapa anterior. </p></div>
        `;
    }
    return `
        <div class="card etapa-card bg-gray-90" data-etapa-id="${etapa.id}">
            <div class="card-body d-flex flex-column">
                <div class="d-flex align-items-center mb-3 gap-3">
                    ${crearCheckbox({
                        id: 'etapa-check-' + etapa.id,
                        name: 'etapa_check',
                        value: etapa.id,
                        checked: false,
                        input_container_class: 'd-inline-block',
                        disabled: (candidatos_totales > 0) ? false : true
                    })}
                    <h6 class="etapa-titulo text-headline-5 fw-bold mb-0">${etapa.nombre}</h6>
                    ${(candidatos_totales > 0 && etapa.nombre !== 'Contratados') ?
                        `<div class="ms-auto">
                            ${crearTag({
                                texto: candidatos_completaron + '/' + candidatos_totales + ' completaron la tarea',
                                class: etapa.nombre === 'Documentos para contratación' ? 'tag-tonal-green' : 'tag-tonal-blue',
                            })}
                        </div>`
                    : ''}
                </div>
                ${candidatos_html}
            </div>
        </div>
    `;
}

/**
 * Ver candidatos descartados en modal.
 *
 * @returns {void}
 * @author Andres Morales
 */
function verCandidatosDescartados() {
    let $contenedor = $('#contenedor-candidatos-descartados');
    let $controles = $('#controles-candidatos-descartados');

    if (candidatos_descartados.length === 0) {
        $controles.addClass('d-none');
        $contenedor.html(`
            <div class="row justify-content-center align-items-center py-5">
                <div class="col-auto text-center">
                    <div class="mb-4">
                        <i class="bi bi-person-x-fill empty-state-icon"></i>
                    </div>
                    <div class="text-gray-30 fw-semibold text-headline-4 mb-3">
                        No hay candidatos descartados
                    </div>
                    <div class="text-gray-50 text-body-2">
                        Los candidatos que descartaste aparecerán aquí
                    </div>
                </div>
            </div>
        `);
    } else {
        $controles.removeClass('d-none');
        let html = '';
        candidatos_descartados.forEach(candidato => {
            html += crearCardCandidato(candidato, 'modal');
        });
        $contenedor.html(html);

        setTimeout(() => {
            inicializarTooltips();
            inicializarEventosModalDescartados();
        }, 100);
    }

    $('#modal-candidatos-descartados').modal('show');
}

